/** Supplied native eggs/terrain; actual bee AI must pollinate, enter and produce in a real native hive. */
final class ApiaryRuntime {
 static final BlockPos CENTER=new BlockPos(1024,90,1024),IRON=CENTER.west(3),COPPER=CENTER.east(3);
 static void run(GameTestHelper h)throws Exception{
  var level=h.getLevel();var server=level.getServer();server.tickRateManager().setTickRate(20);var lodge=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().toString().equals(Profession.LUMBERJACK.buildingId())).findFirst().orElseThrow();var p=ClaimRuntimeTests.vanillaPlayer(level,lodge.owner(),lodge.ownerName());server.getPlayerList().deop(p.getGameProfile());var roster=CommerceService.store(server).professions(p.getUUID());h.assertTrue(ApiaryProduction.supported()&&roster.isActive(Profession.LUMBERJACK),"Exact binary and original active Lumberjack");
  if(roster.track(Profession.LUMBERJACK).completedQuestIds().contains(ApiaryInspection.QUEST)){for(int x=(CENTER.getX()-10)>>4;x<=(CENTER.getX()+10)>>4;x++)for(int z=(CENTER.getZ()-10)>>4;z<=(CENTER.getZ()+10)>>4;z++)level.getChunk(x,z);p.teleportTo(level,CENTER.getX()+.5,CENTER.getY(),CENTER.getZ()+.5,Set.of(),0,0);level.getChunkSource().move(p);h.runAfterDelay(20,()->guard(h,()->restore(h,p,0)));return;}
  h.assertTrue(roster.track(Profession.LUMBERJACK).xp()==3300&&roster.track(Profession.LUMBERJACK).completedQuestIds().size()==19,"Start from actually earned19forestry objectives");prepare(h,p,()->guard(h,()->awaitProduction(h,p,0)));
 }
 static void prepare(GameTestHelper h,ServerPlayer p,Runnable afterSpawn)throws Exception{var level=p.serverLevel();var server=p.server;
  DimensionTravelRuntimeTests.seed(server,6);level.setDayTime(1000);level.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_DAYLIGHT).set(false,server);level.setWeatherParameters(24000,0,false,false);
  for(int x=(CENTER.getX()-11)>>4;x<=(CENTER.getX()+11)>>4;x++)for(int z=(CENTER.getZ()-11)>>4;z<=(CENTER.getZ()+11)>>4;z++){var at=new BlockPos(x*16,CENTER.getY(),z*16);level.getChunk(x,z);ClaimRuntimeTests.ftbUnclaim(level,at);ClaimRuntimeTests.opacUnclaim(level,at);ClaimRuntimeTests.ftbClaim(p,at);ClaimRuntimeTests.opacClaim(level,p.getUUID(),at);}
  for(var pos:BlockPos.betweenClosed(CENTER.offset(-9,-1,-9),CENTER.offset(9,-1,9)))level.setBlock(pos,Blocks.GRASS_BLOCK.defaultBlockState(),18);
  for(var pos:List.of(IRON,COPPER,CENTER.north(3),CENTER.south(3),CENTER.offset(-6,0,-6),CENTER.offset(-6,1,-6)))h.assertTrue(level.getBlockState(pos).isAir(),"Private supplied plot never replaces existing blocks");
  CreateDriveRuntime.place(h,p,IRON,new ItemStack(BuiltInRegistries.ITEM.get(ResourceLocation.parse("productivebees:advanced_oak_beehive"))),IRON.below(),Direction.UP);CreateDriveRuntime.place(h,p,COPPER,new ItemStack(BuiltInRegistries.ITEM.get(ResourceLocation.parse("productivebees:advanced_oak_beehive"))),COPPER.below(),Direction.UP);
  for(var entry:List.of(Map.entry(CENTER.north(3),Items.IRON_BLOCK),Map.entry(CENTER.south(3),Items.COPPER_BLOCK),Map.entry(CENTER.offset(-6,0,-6),Items.OAK_LOG),Map.entry(CENTER.offset(-6,1,-6),Items.OAK_LEAVES),Map.entry(CENTER.north(6),Items.POPPY)))CreateDriveRuntime.place(h,p,entry.getKey(),new ItemStack(entry.getValue()),entry.getKey().below(),Direction.UP);
  enclose(h,p);
  p.teleportTo(level,CENTER.getX()+.5,CENTER.getY(),CENTER.getZ()+.5,Set.of(),0,0);level.getChunkSource().move(p);boolean refused=false;try{ApiaryInspection.validate(p,CENTER);}catch(IllegalStateException expected){refused=true;}h.assertTrue(refused,"Furniture and forgeable stocked items alone cannot prove productive bee work");
  h.runAfterDelay(5,()->guard(h,()->ready(h,p,0,afterSpawn)));
 }

 static void stepNativeHiveTime(ServerPlayer p)throws Exception{var type=Class.forName("cy.jdkdigital.productivebees.common.block.entity.AdvancedBeehiveBlockEntity");var tick=type.getMethod("tick",net.minecraft.world.level.Level.class,BlockPos.class,net.minecraft.world.level.block.state.BlockState.class,type);for(var pos:List.of(IRON,COPPER)){if(!p.serverLevel().isPositionEntityTicking(pos))continue;var hive=p.serverLevel().getBlockEntity(pos);if(!type.isInstance(hive))throw new IllegalStateException("Original native hive changed");for(int n=0;n<2400;n++)tick.invoke(null,p.serverLevel(),pos,p.serverLevel().getBlockState(pos),hive);}}
 static void enclose(GameTestHelper h,ServerPlayer p){var entrance=CENTER.north(9);if(p.serverLevel().getBlockState(entrance).isAir())CreateDriveRuntime.place(h,p,entrance,new ItemStack(Items.OAK_DOOR),entrance.below(),Direction.UP);p.setShiftKeyDown(true);for(int dy=0;dy<=5;dy++)for(int x=-9;x<=9;x++)for(int z=-9;z<=9;z++){if(Math.abs(x)!=9&&Math.abs(z)!=9)continue;if(x==0&&z==-9&&dy<2)continue;var at=CENTER.offset(x,dy,z);if(!p.serverLevel().getBlockState(at).isAir())continue;CreateDriveRuntime.place(h,p,at,new ItemStack(Items.GLASS),at.below(),Direction.UP);}for(int z=-8;z<=8;z++)for(int x=-8;x<=8;x++){var at=CENTER.offset(x,5,z);if(!p.serverLevel().getBlockState(at).isAir())continue;CreateDriveRuntime.place(h,p,at,new ItemStack(Items.GLASS),at.north(),Direction.SOUTH);}p.setShiftKeyDown(false);}
 static void restore(GameTestHelper h,ServerPlayer p,int waited)throws Exception{try{ApiaryInspection.validate(p,CENTER);}catch(IllegalStateException pending){if(waited%100==0)com.mojang.logging.LogUtils.getLogger().info("APIARY_RESTORE_WAIT {} time={} observations={}/{} entities={}/{}: {}",waited,p.serverLevel().getGameTime(),ApiarySavedData.get(p.server).evidence().at(new ApiaryEvidence.Site("minecraft:overworld",IRON.asLong())),ApiarySavedData.get(p.server).evidence().at(new ApiaryEvidence.Site("minecraft:overworld",COPPER.asLong())),((net.minecraft.world.level.block.entity.BeehiveBlockEntity)p.serverLevel().getBlockEntity(IRON)).getOccupantCount(),p.serverLevel().getEntitiesOfClass(Bee.class,new AABB(CENTER).inflate(16)).stream().map(b->b.getUUID()+":"+b.getHivePos()).toList(),pending.getMessage());h.assertTrue(waited<400,"Native saved bees/chunk entities restore without replacements: "+pending.getMessage());h.runAfterDelay(20,()->guard(h,()->restore(h,p,waited+20)));return;}var track=CommerceService.store(p.server).professions(p.getUUID()).track(Profession.LUMBERJACK);h.assertTrue(track.xp()==3600&&track.completedQuestIds().size()==20,"Second JVM retains20earned3600XP");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("APIARY_RESTART_PASSED: real iron/copper native production observations/current working hives,20earned3600XP/original Brenna and native receipts restore");h.succeed();}
 static void spawn(GameTestHelper h,ServerPlayer p,BlockPos hive,String species)throws Exception{var level=p.serverLevel();var egg=(ItemStack)Class.forName("cy.jdkdigital.productivebees.util.BeeCreator").getMethod("getSpawnEgg",ResourceLocation.class).invoke(null,ResourceLocation.parse("productivebees:"+species));p.setItemInHand(InteractionHand.MAIN_HAND,egg);BlacksmithRepairRuntime.near(p,hive.south(2));var at=hive.south(2).below();p.gameMode.useItemOn(p,level,p.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(at).add(0,.5,0),Direction.UP,at,false));h.assertTrue(p.getMainHandItem().isEmpty(),"Actual native configured bee egg is consumed");}
 static void ready(GameTestHelper h,ServerPlayer p,int attempts,Runnable afterSpawn)throws Exception{if(!p.serverLevel().isPositionEntityTicking(CENTER)){h.assertTrue(attempts<80,"Native apiary plot becomes entity ticking");h.runAfterDelay(5,()->guard(h,()->ready(h,p,attempts+1,afterSpawn)));return;}p.server.tickRateManager().setTickRate(200);spawn(h,p,IRON,"iron");spawn(h,p,COPPER,"copper");h.runAfterDelay(5,()->guard(h,()->{assign(h,p,IRON,"iron");assign(h,p,COPPER,"copper");afterSpawn.run();}));}
 static void assign(GameTestHelper h,ServerPlayer p,BlockPos hive,String species){var bee=p.serverLevel().getEntitiesOfClass(Bee.class,new AABB(hive).inflate(7),b->{try{return ApiaryProduction.beeType(b).equals("productivebees:"+species);}catch(ReflectiveOperationException e){return false;}}).stream().findFirst().orElseThrow(()->new IllegalStateException("Actual native egg bee not visible: "+species));bee.setHivePos(hive);h.assertTrue(!bee.hasNectar(),"New native egg bee starts without nectar; AI must actually pollinate");}

 static void awaitProduction(GameTestHelper h,ServerPlayer p,int tick)throws Exception{var level=p.serverLevel();p.teleportTo(level,CENTER.getX()+.5,CENTER.getY(),CENTER.getZ()+.5,Set.of(),0,0);level.getChunkSource().move(p);try{String proof=ApiaryInspection.validate(p,CENTER);finish(h,p,proof);return;}catch(IllegalStateException waiting){if(tick%400==0)com.mojang.logging.LogUtils.getLogger().info("APIARY_WAIT {}: {}",tick,waiting.getMessage());h.assertTrue(tick<5400,"Native pollination/entry/production completes without nectar/comb/proof injection: "+waiting.getMessage());}h.runAfterDelay(20,()->guard(h,()->awaitProduction(h,p,tick+20)));}
 static void finish(GameTestHelper h,ServerPlayer p,String proof)throws Exception{var level=p.serverLevel();var admin=ClaimRuntimeTests.vanillaPlayer(level,UUID.nameUUIDFromBytes("ApiaryInspector".getBytes(java.nio.charset.StandardCharsets.UTF_8)),"ApiaryInspector");p.server.getPlayerList().op(admin.getGameProfile());admin.teleportTo(level,CENTER.getX()+2.5,CENTER.getY(),CENTER.getZ()+.5,Set.of(),0,0);level.getChunkSource().move(admin);String reason="Inspected authored flowering woodland native forage working bees and consent";var nonce=ProfessionInspectionService.review(admin,p,ApiaryInspection.QUEST,CENTER,reason);ClaimRuntimeTests.opacUnclaim(level,CENTER);ClaimRuntimeTests.opacClaim(level,admin.getUUID(),CENTER);boolean denied=false;try{ProfessionInspectionService.confirm(admin,nonce);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied,"Post-review OPAC revocation refuses productive apiary approval");ClaimRuntimeTests.opacUnclaim(level,CENTER);ClaimRuntimeTests.opacClaim(level,p.getUUID(),CENTER);nonce=ProfessionInspectionService.review(admin,p,ApiaryInspection.QUEST,CENTER,reason);ProfessionInspectionService.confirm(admin,nonce);h.assertTrue(CommerceService.store(p.server).professions(p.getUUID()).track(Profession.LUMBERJACK).xp()==3600,"Actual native plot and operator review earn300XP once");p.server.getPlayerList().deop(admin.getGameProfile());CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("APIARY_NATIVE_PASSED: exact Productive Bees13.14.0 native eggs/material debits, actual nectar-free bee AI pollination/hive entry/native comb production for iron/copper, flower/woodland/forage/occupied accessible hive and actual OPAC revocation refusal,20earned3600XP/original Brenna; supplied private terrain/native eggs/time only, no nectar/comb/proof/XP injection");h.succeed();}
 interface Step{void run()throws Exception;}static void guard(GameTestHelper h,Step s){try{s.run();}catch(Exception e){com.mojang.logging.LogUtils.getLogger().error("Native apiary fixture failed",e);h.fail(e.toString());}}
}
